constexpr int16_t SENDSPIN_MIN_DB = -60;
constexpr int16_t SENDSPIN_MAX_DB = 0;
constexpr int16_t SENDSPIN_MIN_TRIM_DB = -24;
constexpr int16_t SENDSPIN_MAX_TRIM_DB = 24;

constexpr uint8_t scaleSendspin16To8(uint16_t value) {
  return static_cast<uint8_t>((static_cast<uint32_t>(value) + 128U) / 257U);
}

constexpr int32_t sendspinDbToLevel(int16_t db) {
  return (static_cast<int32_t>(db - SENDSPIN_MIN_DB) * UINT16_MAX + 30) / 60;
}

constexpr int32_t sendspinDbDeltaToLevel(int16_t db) {
  return db >= 0 ? (static_cast<int32_t>(db) * UINT16_MAX + 30) / 60
                 : (static_cast<int32_t>(db) * UINT16_MAX - 30) / 60;
}

// Gate the original dB level, then apply trim and map the selected dB window to WLED's range.
constexpr uint8_t mapSendspinSpectrum(uint16_t value, int16_t floorDb, int16_t ceilingDb,
                                     int16_t trimDb, int16_t inputGateDb) {
  if (value <= sendspinDbToLevel(inputGateDb)) return 0;
  const int32_t floorLevel = sendspinDbToLevel(floorDb);
  const int32_t ceilingLevel = sendspinDbToLevel(ceilingDb);
  const int32_t adjustedLevel = static_cast<int32_t>(value) + sendspinDbDeltaToLevel(trimDb);
  if (adjustedLevel <= floorLevel) return 0;
  if (adjustedLevel >= ceilingLevel) return UINT8_MAX;
  const int32_t range = ceilingLevel - floorLevel;
  return static_cast<uint8_t>(((adjustedLevel - floorLevel) * UINT8_MAX + range / 2) / range);
}

constexpr bool validSendspinSpectrumConfig(int32_t mapping, int32_t floorDb, int32_t ceilingDb,
                                           int32_t bassTrimDb, int32_t midTrimDb, int32_t trebleTrimDb,
                                           int32_t inputGateDb) {
  return mapping >= 0 && mapping <= 1 && floorDb >= SENDSPIN_MIN_DB && floorDb <= SENDSPIN_MAX_DB &&
         ceilingDb >= SENDSPIN_MIN_DB && ceilingDb <= SENDSPIN_MAX_DB && floorDb < ceilingDb &&
         inputGateDb >= SENDSPIN_MIN_DB && inputGateDb <= SENDSPIN_MAX_DB && inputGateDb < ceilingDb &&
         bassTrimDb >= SENDSPIN_MIN_TRIM_DB && bassTrimDb <= SENDSPIN_MAX_TRIM_DB &&
         midTrimDb >= SENDSPIN_MIN_TRIM_DB && midTrimDb <= SENDSPIN_MAX_TRIM_DB &&
         trebleTrimDb >= SENDSPIN_MIN_TRIM_DB && trebleTrimDb <= SENDSPIN_MAX_TRIM_DB;
}

uint32_t advanceCachedAge(uint32_t ageMs, uint32_t capturedMs, uint32_t now) {
  if (ageMs == UINT32_MAX) return UINT32_MAX;
  const uint32_t elapsed = now - capturedMs;
  return ageMs >= UINT32_MAX - elapsed ? UINT32_MAX - 1 : ageMs + elapsed;
}

static_assert(scaleSendspin16To8(0) == 0 && scaleSendspin16To8(UINT16_MAX) == UINT8_MAX,
              "Raw spectrum mapping must preserve protocol endpoints");
static_assert(scaleSendspin16To8(10336) == 40, "Raw spectrum mapping changed");
static_assert(mapSendspinSpectrum(0, -60, 0, 15, -60) == 0,
              "Pre-trim input gate must preserve exact silence");
static_assert(mapSendspinSpectrum(sendspinDbToLevel(-50), -60, 0, 0, -60) == 43,
              "Compatibility mapping must map the full dB window");
static_assert(mapSendspinSpectrum(sendspinDbToLevel(-50), -60, 0, 15, -60) == 106,
              "Compatibility mapping must apply positive dB trim");
static_assert(mapSendspinSpectrum(10336, -60, 0, 15, -60) == 104,
              "Compatibility mapping must preserve measured-sample calibration");
static_assert(mapSendspinSpectrum(sendspinDbToLevel(-10), -60, 0, 15, -60) == UINT8_MAX,
              "Compatibility mapping must clip high values");
static_assert(mapSendspinSpectrum(sendspinDbToLevel(-50), -60, 0, 15, -50) == 0,
              "Input gate must run before trim");
static_assert(mapSendspinSpectrum(sendspinDbToLevel(-50), -50, -10, 0, -60) == 0 &&
              mapSendspinSpectrum(sendspinDbToLevel(-10), -50, -10, 0, -60) == UINT8_MAX,
              "Compatibility mapping must preserve floor and ceiling boundaries");
static_assert(validSendspinSpectrumConfig(0, -60, 0, 0, 0, 0, -60),
              "Neutral Raw spectrum configuration must remain valid");
static_assert(!validSendspinSpectrumConfig(1, 0, 0, 0, 0, 0, -60) &&
              !validSendspinSpectrumConfig(1, -60, 0, 25, 0, 0, -60) &&
              !validSendspinSpectrumConfig(1, -60, 0, 0, 0, 0, 0),
              "Invalid compatibility parameter combinations must be rejected");

