  PeakSource peakSource_{PeakSource::Transient};
  std::atomic<SpectrumMapping> spectrumMapping_{SpectrumMapping::Raw};
  std::atomic<int16_t> spectrumFloorDb_{SENDSPIN_MIN_DB};
